/**
 * Builds the web UI (apps/web/ui) into one self-contained HTML file and writes
 * it to apps/web/src/ui.generated.ts, which the web server imports. Embedding
 * it as a string keeps `autho web serve` working from the single-file npm
 * bundle and compiled binaries, with no static files to ship.
 *
 * Skips the build when the generated file is newer than every UI source.
 * Usage: bun run scripts/build-ui.ts [--force]
 */
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const webDir = join(import.meta.dirname, "..", "apps", "web");
const uiDir = join(webDir, "ui");
const outFile = join(webDir, "src", "ui.generated.ts");
const force = process.argv.includes("--force");

function newestMtime(path: string): number {
  const stat = statSync(path);
  if (!stat.isDirectory()) return stat.mtimeMs;
  return readdirSync(path).reduce((newest, entry) => Math.max(newest, newestMtime(join(path, entry))), stat.mtimeMs);
}

const inputs = [join(uiDir, "src"), join(uiDir, "index.html"), join(uiDir, "vite.config.ts"), join(webDir, "package.json"), import.meta.path];
if (!force && existsSync(outFile) && statSync(outFile).mtimeMs > Math.max(...inputs.map(newestMtime))) {
  console.log("web UI is up to date");
  process.exit(0);
}

const build = Bun.spawnSync(["bun", "x", "--bun", "vite", "build", "--config", join(uiDir, "vite.config.ts"), "--logLevel", "warn"], {
  cwd: webDir,
  stdout: "inherit",
  stderr: "inherit",
});
if (build.exitCode !== 0) {
  console.error("web UI build failed");
  process.exit(build.exitCode ?? 1);
}

const html = readFileSync(join(uiDir, "dist", "index.html"), "utf8");
writeFileSync(
  outFile,
  `// Generated by scripts/build-ui.ts from apps/web/ui. Do not edit.\nexport const UI_HTML: string = ${JSON.stringify(html)};\n`,
  "utf8",
);
console.log(`web UI built (${(html.length / 1024).toFixed(0)} KiB)`);
